"""Local reference-price ledger using the original A-share position accounting."""
from __future__ import annotations

import hashlib
import json
import math
import os
import re
import sys
import uuid
from contextlib import contextmanager
from dataclasses import asdict
from datetime import datetime, timedelta, timezone

import pandas as pd
from backtest.engines.base import _OpenOrder
from backtest.engines.china_a import ChinaAEngine
from backtest.models import FillRecord, Position, TradeRecord
from fastapi import Depends, FastAPI, HTTPException, Query, Request
from src.api.request_ledger import RequestLedger
from src.api.security import require_auth
from src.config.paths import get_sessions_dir
from src.session.store import SessionStore

_SYMBOL = re.compile(r"^[0-9]{6}\.(?:SH|SZ|BJ)$")
_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")
_PREVIEW_TTL = 60


def _now():
    return datetime.now(timezone.utc)


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))


def _fail(status, code, message):
    raise HTTPException(status, {"error": code, "message": message})


def _positive(value, field):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0:
        raise HTTPException(422, f"{field} must be a finite positive number")
    return float(value)


def _engine(state=None):
    engine = ChinaAEngine({"slippage": 0.0})
    if state is None:
        return engine
    engine.initial_capital = state["initial_cash"]
    engine.capital = state["cash"]
    engine._bar_idx = state["version"]
    for row in state["positions"]:
        row = dict(row)
        row["entry_time"] = pd.Timestamp(row["entry_time"])
        engine.positions[row["symbol"]] = Position(**row)
    for row in state["fills"]:
        row = dict(row)
        row["timestamp"] = pd.Timestamp(row["timestamp"])
        engine.fill_records.append(FillRecord(**row))
    for row in state["native_trades"]:
        row = dict(row)
        row["entry_time"] = pd.Timestamp(row["entry_time"])
        row["exit_time"] = pd.Timestamp(row["exit_time"])
        engine.trades.append(TradeRecord(**row))
    return engine


def _rows(records):
    result = []
    for record in records:
        row = asdict(record)
        result.append({key: value.isoformat() if isinstance(value, pd.Timestamp) else value
                       for key, value in row.items()})
    return result


def _save_engine(state, engine):
    state.update(cash=engine.capital, positions=_rows(engine.positions.values()),
                 fills=_rows(engine.fill_records), native_trades=_rows(engine.trades))


def _defaults():
    engine = _engine()
    return {"initial_cash": engine.initial_capital, "currency": "CNY", "lot_size": 100,
            "fee_model": {"commission_rate": engine.commission_rate,
                          "commission_min": engine.commission_min,
                          "transfer_fee": engine.transfer_fee, "stamp_tax": engine.stamp_tax,
                          "slippage": engine.slippage_rate}}


def _quote(symbol):
    from src.api.mona_workbench_market import market_snapshot

    snapshot = market_snapshot(symbol, "intraday")
    quote = snapshot.get("quote")
    if (snapshot.get("status") != "ok" or snapshot.get("symbol") != symbol
            or snapshot.get("source") != "tencent" or snapshot.get("adjustment") != "none"
            or snapshot.get("interval") != "intraday" or not isinstance(quote, dict)
            or snapshot.get("market_state") not in {"open", "recess", "closed"}):
        _fail(409, "quote_unavailable", "当前没有可用于模拟记账的未复权参考报价，请稍后重试。")
    try:
        price = _positive(quote.get("price"), "quote price")
        as_of = datetime.fromisoformat(quote["as_of"])
        observed = datetime.fromisoformat(snapshot["observed_at"])
        if as_of.tzinfo is None or observed.tzinfo is None or as_of > _now() + timedelta(minutes=5):
            raise ValueError("invalid quote timestamp")
    except (KeyError, ValueError, TypeError, HTTPException) as exc:
        raise HTTPException(409, {"error": "quote_unavailable", "message": "参考报价的价格或时间不完整，本次未记账。"}) from exc
    return {"symbol": symbol, "name": str(quote.get("name") or symbol), "price": price,
            "source": "tencent", "as_of": as_of.isoformat(),
            "observed_at": observed.isoformat(), "market_status": snapshot["market_state"],
            "adjustment": "none"}


def _research(value, symbol):
    if value is None:
        return None
    if (not isinstance(value, dict) or set(value) != {"session_id", "attempt_id"}
            or any(not isinstance(value.get(key), str) or not _ID.fullmatch(value[key]) for key in value)):
        raise HTTPException(422, "Invalid research reference")
    store = SessionStore(get_sessions_dir())
    session = store.get_session(value["session_id"])
    attempt = store.get_attempt(value["session_id"], value["attempt_id"])
    if (session is None or attempt is None or attempt.session_id != session.session_id
            or getattr(attempt.status, "value", attempt.status) != "completed"
            or not attempt.completed_at or not attempt.summary):
        _fail(422, "research_unavailable", "只能关联已经完成且有报告的研究。")
    context, found_user = None, False
    messages = store.get_messages(session.session_id, limit=sys.maxsize)
    for index, message in enumerate(messages):
        if message.role == "assistant" and message.linked_attempt_id == attempt.attempt_id:
            for previous in reversed(messages[:index]):
                if previous.role == "user":
                    found_user = True
                    context = previous.metadata.get("research")
                    break
            break
    if not found_user:
        context = session.config.get("mona_workbench")
    if not isinstance(context, dict) or context.get("symbol") != symbol:
        _fail(422, "research_unavailable", "研究报告与本次交易的股票不一致。")
    summary = attempt.summary
    return {**value, "title": session.title, "summary": summary,
            "summary_sha256": hashlib.sha256(summary.encode()).hexdigest(),
            "completed_at": attempt.completed_at,
            **{key: context[key] for key in ("task", "mode") if key in context}}


class PaperAccountStore:
    def __init__(self):
        self.ledger = RequestLedger()

    @contextmanager
    def connection(self):
        with self.ledger._connection() as connection:
            connection.execute("CREATE TABLE IF NOT EXISTS paper_account (id INTEGER PRIMARY KEY CHECK(id=1), state_json TEXT NOT NULL)")
            connection.execute("CREATE TABLE IF NOT EXISTS paper_previews (preview_id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, trade_id TEXT)")
            connection.execute("CREATE TABLE IF NOT EXISTS paper_trades (trade_id TEXT PRIMARY KEY, seq INTEGER NOT NULL UNIQUE, payload_json TEXT NOT NULL)")
            connection.execute("CREATE TABLE IF NOT EXISTS paper_receipts (request_id TEXT PRIMARY KEY, response_json TEXT NOT NULL)")
            connection.commit()
            connection.execute("BEGIN IMMEDIATE")
            yield connection

    @staticmethod
    def state(connection):
        row = connection.execute("SELECT state_json FROM paper_account WHERE id=1").fetchone()
        return json.loads(row[0]) if row else None

    @staticmethod
    def save(connection, state):
        connection.execute("INSERT OR REPLACE INTO paper_account(id,state_json) VALUES(1,?)", (_json(state),))

    @staticmethod
    def receipt(connection, request_id, body):
        connection.execute("INSERT INTO paper_receipts(request_id,response_json) VALUES(?,?)", (request_id, _json(body)))
        connection.execute("UPDATE requests SET status='completed',response_status=200,response_json=?,response_content_type='application/json',updated_at=? WHERE request_id=?",
                           (_json(body), _now().isoformat(), request_id))

    @staticmethod
    def existing(connection, request_id):
        row = connection.execute("SELECT response_json FROM paper_receipts WHERE request_id=?", (request_id,)).fetchone()
        return json.loads(row[0]) if row else None

    def initialize(self, request_id, initial_cash):
        cash = _positive(initial_cash, "initial_cash")
        if cash > 1_000_000_000_000:
            raise HTTPException(422, "initial_cash exceeds supported limit")
        with self.connection() as connection:
            prior = self.existing(connection, request_id)
            if prior is not None:
                return prior
            if self.state(connection) is not None:
                _fail(409, "account_exists", "模拟账户已创建，不能重复设置资金。")
            state = {"initial_cash": cash, "cash": cash, "version": 1,
                     "created_at": _now().isoformat(), "positions": [], "fills": [], "native_trades": [], "last_quotes": {}}
            self.save(connection, state)
            summary = self.summary(state)
            summary.update(unrealized_pnl=0, equity=cash, total_pnl=0, total_return=0)
            body = {"status": "ok", "defaults": _defaults(), "account": summary,
                    "positions": [], "valuation": {"complete": True, "cached": False,
                    "missing_symbols": [], "as_of": None}}
            self.receipt(connection, request_id, body)
            return body

    @staticmethod
    def summary(state):
        realized = sum(row["pnl"] - row["commission"] for row in state["native_trades"])
        return {key: state[key] for key in ("initial_cash", "cash", "version", "created_at")} | {
            "realized_pnl": realized, "realized_gross_pnl": sum(row["pnl"] for row in state["native_trades"]),
            "unrealized_pnl": None, "equity": None, "total_pnl": None, "total_return": None}

    def account(self):
        with self.connection() as connection:
            state = self.state(connection)
        if state is None:
            return {"status": "uninitialized", "defaults": _defaults(), "account": None,
                    "positions": [], "valuation": {"complete": False, "cached": False, "missing_symbols": [], "as_of": None}}
        engine = _engine(state)
        rows, missing, timestamps = [], [], []
        cached = False
        for symbol, position in engine.positions.items():
            try:
                quote = _quote(symbol)
                mark_status = "reference_quote"
            except HTTPException:
                quote = state["last_quotes"].get(symbol)
                mark_status = "last_recorded_quote" if quote else "unavailable"
                cached = cached or bool(quote)
            price = quote["price"] if quote else None
            value = price * position.size if price is not None else None
            cost = position.entry_price * position.size + position.entry_commission
            pnl = engine._calc_pnl(symbol, 1, position.size, position.entry_price, price) - position.entry_commission if price is not None else None
            if quote:
                timestamps.append(quote["as_of"])
            else:
                missing.append(symbol)
            rows.append({"symbol": symbol, "name": quote["name"] if quote else symbol,
                         "quantity": position.size, "available_quantity": position.size,
                         "average_cost": cost / position.size, "cost_basis": cost,
                         "mark_price": price, "mark_as_of": quote["as_of"] if quote else None,
                         "quote_source": quote["source"] if quote else None,
                         "mark_status": mark_status, "market_value": value, "unrealized_pnl": pnl})
        summary = self.summary(state)
        if not missing:
            equity = engine.capital + sum(row["market_value"] for row in rows)
            summary.update(unrealized_pnl=sum(row["unrealized_pnl"] for row in rows), equity=equity,
                           total_pnl=equity-state["initial_cash"], total_return=(equity/state["initial_cash"]-1)*100)
        return {"status": "partial" if missing or cached else "ok", "defaults": _defaults(),
                "account": summary, "positions": rows,
                "valuation": {"complete": not missing, "cached": cached, "missing_symbols": missing,
                              "as_of": min(timestamps) if timestamps else None}}

    def preview(self, symbol, side, quantity):
        if not isinstance(symbol, str) or not _SYMBOL.fullmatch(symbol) or side not in {"buy", "sell"}:
            raise HTTPException(422, "Invalid symbol or side")
        size = _positive(quantity, "quantity")
        if not size.is_integer():
            _fail(422, "invalid_quantity", "股数必须是整数。")
        quote = _quote(symbol)
        with self.connection() as connection:
            state = self.state(connection)
            if state is None:
                _fail(409, "account_uninitialized", "请先设置模拟资金。")
            engine = _engine(state)
            if side == "buy" and engine.round_size(size, quote["price"]) != size:
                _fail(422, "invalid_quantity", "买入数量必须是100股的整数倍。")
            position = engine.positions.get(symbol)
            available = position.size if position else 0
            if side == "sell" and size > available:
                _fail(422, "insufficient_quantity", "卖出数量超过模拟持仓。")
            price = quote["price"]
            fee = engine.calc_commission(size, price, 1, is_open=side == "buy")
            notional = size * price
            delta = -notional-fee if side == "buy" else notional-fee
            if engine.capital + delta < 0:
                _fail(422, "insufficient_cash", "模拟资金不足，费用已包含在本次支出中。")
            result = {"status": "ready", "preview_id": uuid.uuid4().hex, "expires_at": (_now()+timedelta(seconds=_PREVIEW_TTL)).isoformat(),
                      "account_version": state["version"], "symbol": symbol, "name": quote["name"],
                      "side": side, "quantity": int(size), "lot_size": 100, "price": price,
                      "notional": notional, "fee": fee, "cash_delta": delta,
                      "cash_after": engine.capital+delta, "available_quantity": available, "quote": quote}
            connection.execute("DELETE FROM paper_previews WHERE trade_id IS NULL AND json_extract(payload_json,'$.expires_at') < ?", (_now().isoformat(),))
            connection.execute("INSERT INTO paper_previews(preview_id,payload_json) VALUES(?,?)", (result["preview_id"], _json(result)))
            return result

    def trade(self, request_id, payload):
        if not isinstance(payload, dict) or not set(payload) <= {"preview_id", "note", "research"}:
            raise HTTPException(422, "Invalid paper trade fields")
        preview_id = payload.get("preview_id")
        if not isinstance(preview_id, str) or not re.fullmatch("[a-f0-9]{32}", preview_id):
            raise HTTPException(422, "Invalid preview reference")
        note = payload.get("note")
        if note is None:
            note = ""
        if not isinstance(note, str) or len(note) > 500 or "\x00" in note:
            raise HTTPException(422, "交易理由最多500字。")
        with self.connection() as connection:
            prior = self.existing(connection, request_id)
            if prior is not None:
                return prior
            row = connection.execute("SELECT payload_json,trade_id FROM paper_previews WHERE preview_id=?", (preview_id,)).fetchone()
            if row is None:
                _fail(409, "preview_expired", "交易确认已失效，请重新获取参考报价。")
            if row["trade_id"]:
                _fail(409, "preview_consumed", "这次模拟交易已经记账，请查看交易记录；如需再次交易，请重新确认。")
            preview = json.loads(row["payload_json"])
            state = self.state(connection)
            if datetime.fromisoformat(preview["expires_at"]) <= _now():
                _fail(409, "preview_expired", "报价已过期，请重新确认。")
            if state["version"] != preview["account_version"]:
                _fail(409, "account_changed", "模拟账户已变化，请重新确认。")
            research = _research(payload.get("research"), preview["symbol"])
            engine = _engine(state)
            symbol, size, price = preview["symbol"], preview["quantity"], preview["price"]
            ts = pd.Timestamp(_now())
            if preview["side"] == "buy":
                order = _OpenOrder(symbol, 1, price, size, 1.0, engine._calc_margin(symbol, size, price, 1.0),
                                   engine.calc_commission(size, price, 1, is_open=True))
                if order.cost > engine.capital:
                    _fail(409, "insufficient_cash", "模拟资金不足，请重新确认。")
                if symbol in engine.positions:
                    engine._execute_position_increase(order, ts)
                else:
                    engine._execute_open_order(order, ts)
                realized, gross = None, None
            else:
                before = engine.positions.get(symbol)
                if before is None or size > before.size:
                    _fail(409, "account_changed", "模拟持仓已变化，请重新确认。")
                if size == before.size:
                    engine._close_position(symbol, price, ts, "paper_reference")
                else:
                    order = engine._plan_reduction(before, before.size-size, price)
                    engine._execute_partial_reduction(order, ts)
                native = engine.trades[-1]
                gross, realized = native.pnl, native.pnl-native.commission
            if engine.capital < 0 or not math.isfinite(engine.capital):
                raise RuntimeError("invalid native paper capital")
            state["version"] += 1
            state["last_quotes"][symbol] = preview["quote"]
            _save_engine(state, engine)
            trade = {"trade_id": uuid.uuid4().hex, "request_id": request_id, "preview_id": preview_id,
                     **{key: preview[key] for key in ("symbol", "name", "side", "quantity", "price", "notional", "fee", "quote")},
                     "realized_pnl": realized, "realized_gross_pnl": gross, "cash_after": engine.capital,
                     "quantity_after": engine.positions[symbol].size if symbol in engine.positions else 0,
                     "note": note, "research": research, "recorded_at": ts.isoformat(), "account_version": state["version"]}
            self.save(connection, state)
            connection.execute("INSERT INTO paper_trades(trade_id,seq,payload_json) VALUES(?,?,?)", (trade["trade_id"], state["version"], _json(trade)))
            connection.execute("UPDATE paper_previews SET trade_id=? WHERE preview_id=?", (trade["trade_id"], preview_id))
            body = {"trade": trade}
            self.receipt(connection, request_id, body)
            return body

    def history(self, limit, offset):
        with self.connection() as connection:
            total = connection.execute("SELECT COUNT(*) FROM paper_trades").fetchone()[0]
            rows = connection.execute("SELECT payload_json FROM paper_trades ORDER BY seq DESC LIMIT ? OFFSET ?", (limit, offset)).fetchall()
        return {"items": [json.loads(row[0]) for row in rows], "total": total, "limit": limit, "offset": offset}


def reconcile_paper_request(ledger, request_id):
    """Recover committed business receipts without dispatching a second trade."""
    with ledger._connection() as connection:
        exists = connection.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='paper_receipts'").fetchone()
        if exists is None:
            return
        row = connection.execute("SELECT response_json FROM paper_receipts WHERE request_id=?", (request_id,)).fetchone()
        if row:
            connection.execute("UPDATE requests SET status='completed',response_status=200,response_json=?,response_content_type='application/json',updated_at=? WHERE request_id=?",
                               (row[0], _now().isoformat(), request_id))


def register_mona_paper_account(app: FastAPI):
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    def fields(request, allowed, required=()):
        query = request.query_params
        if (not set(query) <= set(allowed) or not set(required) <= set(query)
                or any(len(query.getlist(key)) != 1 for key in query)):
            raise HTTPException(422, "Invalid paper query fields")

    @app.get("/mona/paper/account", dependencies=[Depends(require_auth)])
    def account(request: Request):
        fields(request, ())
        return PaperAccountStore().account()

    @app.post("/mona/paper/account", dependencies=[Depends(require_auth)])
    def initialize(request: Request, payload: dict):
        if set(payload) != {"initial_cash"}:
            raise HTTPException(422, "Only initial_cash is accepted")
        return PaperAccountStore().initialize(request.headers["x-mona-request-id"], payload["initial_cash"])

    @app.get("/mona/paper/preview", dependencies=[Depends(require_auth)])
    def preview(request: Request, symbol: str, side: str, quantity: int = Query(..., gt=0)):
        fields(request, ("symbol", "side", "quantity"), ("symbol", "side", "quantity"))
        try:
            return PaperAccountStore().preview(symbol, side, quantity)
        except HTTPException as exc:
            if isinstance(exc.detail, dict):
                return {"status": "unavailable", "code": exc.detail["error"], "message": exc.detail["message"]}
            raise

    @app.post("/mona/paper/trades", dependencies=[Depends(require_auth)])
    def trade(request: Request, payload: dict):
        return PaperAccountStore().trade(request.headers["x-mona-request-id"], payload)

    @app.get("/mona/paper/trades", dependencies=[Depends(require_auth)])
    def history(request: Request, limit: int = Query(20, ge=1, le=100), offset: int = Query(0, ge=0, le=1_000_000)):
        fields(request, ("limit", "offset"))
        return PaperAccountStore().history(limit, offset)
